  "about": "慈堤為戰略需要於1969年興建，隔成內側慈湖與外側海域。2026年金門國家公園管理處公告落日觀海平台維護整修及施工場域管理，支持該平台工程角色；本文不將其延伸為整條慈堤道路、湖岸、海岸均屬同一現行權管或產權。2025年另有慈堤海灘與慈湖湖灘清潔合作備忘錄，屬湖海灘環境協作；道路及各設施管理維護範圍仍待逐項核實。",
