  "about": "獅山砲陣地又稱震東坑道，今日透過陣地空間、設備展示與砲操介紹戰地歷史。金門縣觀光景點門票收費辦法第2、3條列縣府為主管機關，景點範圍包含獅山砲陣地。觀光處2026年甄選公告另列砲操及設施維護等工作，但公告不證明已完成甄用、人員到任或現行整場管理安排；現場管理與委外契約仍待確認。",
