  "about": "黃廷參三落大厝列於金門縣歷史建築名冊，官方旅遊店家資料以古厝小舖介紹，稱由後代接手經營。文化資產紀錄、店家日常經營及建物所有權是不同層次；此處按公開來源說明經營者，不推定個人產權或由國家公園經營。",
