    "行前查最新公告，不沿用2026年1月閉館公告判斷當日狀態。",
    "歷史洋樓的門檻及可通行範圍先洽館方，雨天注意濕滑。",
    "不任意移動展品；影片、借用與解說依整修重開後現場安排。"
