  "about": "本館位於水頭57地號洋樓，以海外生活與家鄉建築的往來介紹僑鄉文化。內政部國家公園署金門國家公園管理處完成整修並公告2026年8月10日重新開館；管理維護資訊不等同建物所有權認定。",
