    statusNotice: '2026年5月展示更新重新開幕 · 一般08:30–17:00 · 除夕休館 · 非即時開放狀態，最新公告優先。',
    paragraphs: ['在水頭聚落，金水國小把僑民返鄉興學的故事留在校舍與院落中。從正面的中西裝飾到內部學習空間，可以比較海外經驗如何轉化為家鄉的教育建設。', '展示館在2026年5月更新重新開幕，以文物、影像及互動展示連結僑鄉與移民文化。將建築觀察和現場展示一起閱讀，再接得月樓與聚落散步。'],
    advice: ['建議預留30–45分鐘；合排水頭聚落時另留散步和等待時間。', '一般開放時間不是當日營運保證，出發前查最新公告。', '歷史校舍的門檻與轉折需留意，輪椅與推車先詢問當日可通行路線。', '展示更新後的服務與借用條件先向現場確認，勿任意移動展品。'],
    features: ['1932年僑民集資興學的歷史校舍。', '院落格局與中西合璧的正面裝飾。', '海外移民與家鄉教育的展示主題。', '可串接得月樓與水頭聚落。'],
    about: '金水學校由水頭旅外鄉僑於1932年集資興建，見證海外移民對家鄉教育與聚落發展的投入。金門國家公園管理處於2026年辦理展示更新與重新開幕，延續校舍的文化展示用途；此處說明展示館管理維護，不推定建築所有權。',
    management: {name:'內政部國家公園署金門國家公園管理處',sourceUrl:'https://www.kmnp.gov.tw/ch/titlelist/latest-news/4319'},
