    features: ['塔樓與相鄰洋樓的防禦布局。', '槍孔與瞭望等建築細節。', '黃輝煌及印尼華僑文化展示。', '可與水頭聚落其他館舍串訪。'],
    about: '得月樓建築群連結黃輝煌的海外經商、返鄉建屋與家族防禦需求。名稱取自「近水樓台先得月」，今日透過文化展示認識僑鄉故事。官方來源對槍樓興建年代有1931及1933年的不同記載，詳見保留專題。國家公園署主題網於2026年9月8日更新的資料明載，得月樓由金門國家公園管理處維護管理；此為展示館維護管理資訊，不等同建物所有權認定。',
